test('subtitlecat: TW-derived search rows are probed after clean rows', async () => {
  const searchHtml = fixtureText('search-SSIS-001.html');
  const twDetail = '<html><head><title>ssis-001-zhTW subtitles</title></head><body>'
    + '<h2>All language subtitles for ssis-001-zhTW</h2>'
    + '<a href="/subs/1707/ssis-001-zhTW-zh-TW.srt">Download</a></body></html>';
  const cleanDetail = '<html><head><title>SSIS-001 T subtitles</title></head><body>'
    + '<h2>All language subtitles for SSIS-001 T</h2>'
    + '<a href="/subs/266/SSIS-001 T-zh-CN.srt">Download</a>'
    + '<a href="/subs/267/SSIS-001 T-en.srt">Download</a></body></html>';
  const calls = [];
  const http = {
    calls,
    async getFollow(url) {
      calls.push(url);
      const text = url.includes('index.php')
        ? searchHtml
        : url.includes('subs/1707/') ? twDetail : cleanDetail;
      return { status: 200, text, buffer: Buffer.from(text), headers: {}, url, route: 'proxy', ms: 1 };
    },
  };
  const found = await createSubtitlecatSource(http).find('SSIS-001');
  assert.ok(found);
  assert.equal(found.srtName, 'SSIS-001 T-zh-CN.srt');
  assert.ok(!calls.some((u) => u.includes('subs/1707/')), 'TW-hinted row must not be probed first');
});

test('subtitlecat: find surfaces network errors instead of claiming "no subtitle"', async () => {
  const http = makeStubHttp({ [SEARCH_URL('ABP-984')]: { throw: Object.assign(new Error('ENOTFOUND'), { code: 'ENOTFOUND' }) } });
  await assert.rejects(() => createSubtitlecatSource(http).find('ABP-984'), /ENOTFOUND/);
});

test('subtitlecat: find rejects non-200 search responses and CF challenges', async () => {
  const http403 = makeStubHttp({ [SEARCH_URL('ABP-984')]: { status: 403, text: 'Just a moment...' } });
  await assert.rejects(() => createSubtitlecatSource(http403).find('ABP-984'), /HTTP_403/);

  const http503 = makeStubHttp({ [SEARCH_URL('ABP-984')]: { status: 200, text: '<title>Just a moment...</title>' } });
  await assert.rejects(() => createSubtitlecatSource(http503).find('ABP-984'), /CF_CHALLENGE/);
});

// ---------------------------------------------------------------------------
// source-subtitlecat: download()
// ---------------------------------------------------------------------------
test('subtitlecat: download returns raw srt bytes', async () => {
  const body = fixtureBytes('zh-CN.srt');
  const url = 'https://www.subtitlecat.com/subs/822/IPX-920.zh.LLW-zh-CN.srt';
  const http = makeStubHttp({
    [url]: { buffer: body, headers: { 'content-type': 'application/octet-stream' } },
  });
  const src = createSubtitlecatSource(http);
  const { buffer } = await src.download({ url, detailUrl: 'https://www.subtitlecat.com/subs/472/IPX-920.zh.LLW.html' });
  assert.deepEqual(buffer, body);
  assert.equal(http.calls[0].opts.headers.Referer, 'https://www.subtitlecat.com/subs/472/IPX-920.zh.LLW.html');
});

test('subtitlecat: download rejects HTTP errors, HTML and empty bodies', async () => {
  const src = (entry) => createSubtitlecatSource(makeStubHttp({ 'https://example.test/a.srt': entry }));
  await assert.rejects(() => src({ status: 404, text: 'nope' }).download({ url: 'https://example.test/a.srt' }), /HTTP_404/);
  await assert.rejects(
    () => src({ status: 200, text: '<html>challenge</html>', headers: { 'content-type': 'text/html' } }).download({ url: 'https://example.test/a.srt' }),
    /UNEXPECTED_HTML/,
  );
  await assert.rejects(() => src({ status: 200, buffer: Buffer.alloc(0) }).download({ url: 'https://example.test/a.srt' }), /EMPTY_DOWNLOAD/);
  await assert.rejects(() => createSubtitlecatSource(makeStubHttp({})).download(null), /TypeError|found\.url/);
});

// ---------------------------------------------------------------------------
// verify: encoding detection
// ---------------------------------------------------------------------------
test('verify: decodeToUtf8 strips the UTF-8 BOM (real IPX-451-style sample)', () => {
  const out = decodeToUtf8(fixtureBytes('zh-CN-bom.srt'));
  assert.equal(out.encoding, 'utf-8');
  assert.equal(out.hadBom, true);
  assert.equal(out.text.charCodeAt(0), 0x31); // '1'
  assert.ok(!out.text.includes('\uFEFF'));
  assert.ok(out.text.includes('-->'));
});

test('verify: decodeToUtf8 detects GB18030', () => {
  const honest = fixtureText('zh-CN.srt');
  const out = decodeToUtf8(fixtureBytes('zh-CN.gb18030.srt'));
  assert.equal(out.encoding, 'gb18030');
  assert.equal(out.hadBom, false);
  assert.equal(out.text, honest);
  assert.ok(out.text.includes('本片由'));
});

test('verify: decodeToUtf8 detects BIG5', () => {
  const honest = fixtureText('zh-TW.srt');
  const out = decodeToUtf8(fixtureBytes('zh-TW.big5.srt'));
  assert.equal(out.encoding, 'big5');
  assert.equal(out.hadBom, false);
  assert.equal(out.text, honest);
  assert.ok(out.text.includes('性慾'));
});

test('verify: decodeToUtf8 keeps plain UTF-8 and handles empty input', () => {
  assert.equal(decodeToUtf8(fixtureBytes('zh-CN.srt')).encoding, 'utf-8');
  assert.equal(decodeToUtf8(Buffer.alloc(0)).text, '');
});

// ---------------------------------------------------------------------------
// verify: SRT parsing
// ---------------------------------------------------------------------------
test('verify: parseSrt handles CRLF/LF mixing and missing indexes', () => {
  const crlf = '1\r\n00:00:01,000 --> 00:00:02,500\r\n第一句\r\n\r\n';
  const lf = '2\n00:00:03,000 --> 00:00:04,250\n第二句\n';
  const parsed = parseSrt(crlf + lf);
  assert.equal(parsed.count, 2);
  assert.deepEqual(parsed.problems, []);
  assert.equal(parsed.cues[0].start, 1);
  assert.equal(parsed.cues[0].end, 2.5);
  assert.equal(parsed.cues[0].text, '第一句');
  assert.equal(parsed.cues[1].start, 3);
  assert.equal(parsed.lastEndSec, 4.25);
});

test('verify: parseSrt reports reversed and out-of-order timings', () => {
  const text = [
    '1', '00:00:05,000 --> 00:00:06,000', 'late',
    '', '2', '00:00:02,000 --> 00:00:03,000', 'early',
    '', '3', '00:00:09,000 --> 00:00:08,000', 'reversed', '',
  ].join('\n');
  const parsed = parseSrt(text);
  assert.equal(parsed.count, 3);
  assert.ok(parsed.problems.includes('reversed_timing'));
  assert.ok(parsed.problems.includes('out_of_order'));
});

test('verify: parseSrt on the real 60-cue fixture', () => {
  const parsed = parseSrt(fixtureText('zh-CN.srt'));
  assert.equal(parsed.count, 60);
  assert.deepEqual(parsed.problems, []);
  assert.ok(parsed.lastEndSec > 200);
});

// ---------------------------------------------------------------------------
// verify: Simplified/Traditional classification
// ---------------------------------------------------------------------------
test('verify: classifyChinese distinguishes zh-CN from zh-TW', () => {
  const cn = classifyChinese(fixtureText('zh-CN.srt'));
  const tw = classifyChinese(fixtureText('zh-TW.srt'));
  assert.equal(cn.verdict, 'zh-CN');
  assert.equal(cn.traditionalHits, 0);
  assert.equal(tw.verdict, 'zh-TW');
  assert.equal(tw.simplifiedHits, 0);
  assert.equal(classifyChinese('Hello world').verdict, 'unknown');
  assert.equal(classifyChinese('').verdict, 'unknown');
});

// ---------------------------------------------------------------------------
// verify: overall verdict
// ---------------------------------------------------------------------------
test('verify: Traditional subtitle is rejected as traditional_only', () => {
  const result = verifySubtitle({ buffer: fixtureBytes('zh-TW.srt'), expectedDurationMin: 168 });
  assert.equal(result.ok, false);
  assert.equal(result.verdict, 'zh-TW');
  assert.equal(result.reason, 'traditional_only');
  assert.ok(result.cues > 0);
});

test('verify: allowTraditional opts out of the Traditional rejection', () => {
  const result = verifySubtitle({ buffer: fixtureBytes('zh-TW.srt'), allowTraditional: true });
  assert.equal(result.ok, true);
  assert.equal(result.verdict, 'zh-TW');
});

test('verify: Simplified subtitle passes; duration mismatch is a warning only', () => {
  const parsed = parseSrt(fixtureText('zh-CN.srt'));
  const expected = parsed.lastEndSec / 60;
  const ok = verifySubtitle({ buffer: fixtureBytes('zh-CN.srt'), expectedDurationMin: expected, lang: 'zh' });
  assert.equal(ok.ok, true);
  assert.equal(ok.verdict, 'zh-CN');
  assert.equal(ok.reason, null);
  assert.deepEqual(ok.warnings, []);
  assert.equal(ok.cues, 60);
  assert.ok(Math.abs(ok.durationDeltaMin) < 0.01);

  const mismatch = verifySubtitle({ buffer: fixtureBytes('zh-CN.srt'), expectedDurationMin: expected + 10 });
  assert.equal(mismatch.ok, true);
  assert.ok(mismatch.warnings.includes('duration_mismatch'));
  assert.ok(mismatch.durationDeltaMin > 5);
});

test('verify: structural failures reject', () => {
  const reversed = ['1', '00:00:09,000 --> 00:00:08,000', 'x', ''].join('\n');
  const r1 = verifySubtitle({ buffer: Buffer.from(reversed, 'utf8') });
  assert.equal(r1.ok, false);
  assert.equal(r1.reason, 'reversed_timing');

  const r2 = verifySubtitle({ buffer: Buffer.from('not a subtitle at all', 'utf8') });
  assert.equal(r2.ok, false);
  assert.equal(r2.reason, 'no_cues');

  const r3 = verifySubtitle({ buffer: Buffer.alloc(0) });
  assert.equal(r3.ok, false);
  assert.equal(r3.reason, 'empty');
});

test('verify: GB18030 buffer still verifies as Simplified Chinese', () => {
  const result = verifySubtitle({ buffer: fixtureBytes('zh-CN.gb18030.srt') });
  assert.equal(result.encoding, 'gb18030');
  assert.equal(result.ok, true);
  assert.equal(result.verdict, 'zh-CN');
  assert.equal(result.cues, 60);
});

