// install
// ---------------------------------------------------------------------------
test('install: subtitlePathFor keeps the directory and replaces the extension', () => {
  assert.equal(subtitlePathFor(path.join('C:', 'vids', 'IPX-920.mp4')), path.join('C:', 'vids', 'IPX-920.srt'));
  assert.equal(subtitlePathFor(path.join('/media', 'a.b', 'ABP-984.4K.mkv')), path.join('/media', 'a.b', 'ABP-984.4K.srt'));
});

test('install: writes UTF-8/no-BOM/LF sibling srt and reports bytes', async () => {
  const dir = await fsp.mkdtemp(path.join(os.tmpdir(), 'subs-install-'));
  const video = path.join(dir, 'IPX-920 テスト.mp4');
  const sourceText = fixtureText('zh-CN.srt');
  const { path: written, bytes } = await installSubtitle(video, fixtureBytes('zh-CN.gb18030.srt'));

  assert.equal(written, subtitlePathFor(video));
  const raw = await fsp.readFile(written);
  assert.equal(bytes, raw.length);
  assert.ok(!raw.subarray(0, 3).equals(Buffer.from([0xef, 0xbb, 0xbf])));
  const text = raw.toString('utf8');
  assert.ok(!text.includes('\r'));
  assert.equal(text, sourceText);
  // matches what verify expects from the same bytes
  assert.equal(verifySubtitle({ buffer: raw }).ok, true);

  await fsp.rm(dir, { recursive: true, force: true });
});

test('install: rejects an empty subtitle', async () => {
  const dir = await fsp.mkdtemp(path.join(os.tmpdir(), 'subs-install-'));
  const video = path.join(dir, 'x.mp4');
  await assert.rejects(() => installSubtitle(video, Buffer.alloc(0)), /EMPTY_SUBTITLE/);
  await assert.rejects(() => installSubtitle(video, Buffer.from('   \n\n', 'utf8')), /EMPTY_SUBTITLE/);
  await fsp.rm(dir, { recursive: true, force: true });
});
